from typing import List
class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        INF = float('inf')
        def solve(swap_last):
            a, b = nums1[n-1], nums2[n-1]
            if swap_last:
                a, b = b, a
            cnt = 1 if swap_last else 0
            for i in range(n - 1):
                x, y = nums1[i], nums2[i]
                if x <= a and y <= b:
                    continue
                if x <= b and y <= a:
                    cnt += 1
                else:
                    return INF
            return cnt
        res = min(solve(False), solve(True))
        return res if res < INF else -1

