class Solution {
public:
    int minOperations(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        const int INF = INT_MAX / 2;
        auto solve = [&](bool swapLast) {
            int a = nums1[n-1], b = nums2[n-1];
            if (swapLast) swap(a, b);
            int cnt = swapLast ? 1 : 0;
            for (int i = 0; i < n - 1; ++i) {
                int x = nums1[i], y = nums2[i];
                if (x <= a && y <= b) continue;
                if (x <= b && y <= a) ++cnt;
                else return INF;
            }
            return cnt;
        };
        int res = min(solve(false), solve(true));
        return res >= INF ? -1 : res;
    }
};

