class Solution {
    public int minOperations(int[] nums1, int[] nums2) {
        int n = nums1.length;
        final int INF = Integer.MAX_VALUE / 2;
        java.util.function.BooleanSupplier[] solvers = {
            () -> {
                int a = nums1[n-1], b = nums2[n-1];
                int cnt = 0;
                for (int i = 0; i < n - 1; ++i) {
                    if (nums1[i] <= a && nums2[i] <= b) continue;
                    if (nums1[i] <= b && nums2[i] <= a) ++cnt;
                    else return INF;
                }
                return cnt;
            },
            () -> {
                int a = nums2[n-1], b = nums1[n-1];
                int cnt = 1;
                for (int i = 0; i < n - 1; ++i) {
                    if (nums1[i] <= a && nums2[i] <= b) continue;
                    if (nums1[i] <= b && nums2[i] <= a) ++cnt;
                    else return INF;
                }
                return cnt;
            }
        };
        int res = Math.min(solvers[0].getAsBoolean(), solvers[1].getAsBoolean());
        return res >= INF ? -1 : res;
    }
}

