var minOperations = function(nums1, nums2) {
    const n = nums1.length;
    const INF = Infinity;
    const solve = (swapLast) => {
        let a = nums1[n-1], b = nums2[n-1];
        if (swapLast) [a, b] = [b, a];
        let cnt = swapLast ? 1 : 0;
        for (let i = 0; i < n - 1; ++i) {
            const x = nums1[i], y = nums2[i];
            if (x <= a && y <= b) continue;
            if (x <= b && y <= a) ++cnt;
            else return INF;
        }
        return cnt;
    };
    const res = Math.min(solve(false), solve(true));
    return res === INF ? -1 : res;
};
